package com.fileproc.service

import java.io.File
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.CountDownLatch
import javax.naming.Context
import javax.naming.directory.InitialDirContext
import javax.naming.directory.SearchControls
import java.util.Hashtable

class LdapConnectionPool(private val ldapUrl: String) {
    private val env = Hashtable<String, String>().apply {
        put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory")
        put(Context.PROVIDER_URL, ldapUrl)
        put(Context.SECURITY_AUTHENTICATION, "simple")
        put(Context.SECURITY_PRINCIPAL, "cn=admin,dc=corp,dc=local")
        put(Context.SECURITY_CREDENTIALS, System.getenv("LDAP_BIND_PW") ?: "")
    }

    fun getContext(): InitialDirContext = InitialDirContext(env)
}

interface FilterEncoder {
    fun encode(value: String): String
}

class Rfc2254FilterEncoder : FilterEncoder {
    // RFC 2254 special characters that must be escaped
    private val specialChars = mapOf(
        '\\' to "\\5c",
        '*' to "\\2a",
        '(' to "\\28",
        ')' to "\\29",
        '\u0000' to "\\00"
    )

    override fun encode(value: String): String {
        val sb = StringBuilder(value.length * 2)
        for (ch in value) {
            val escaped = specialChars[ch]
            if (escaped != null) {
                sb.append(escaped)
            } else {
                sb.append(ch)
            }
        }
        return sb.toString()
    }
}

class FileProcessingService(
    private val ldapPool: LdapConnectionPool,
    private val filterEncoder: FilterEncoder,
    private val baseDn: String = "ou=users,dc=corp,dc=local"
) {
    private val shutdownRequested = AtomicBoolean(false)
    private val shutdownLatch = CountDownLatch(1)
    private val processingActive = AtomicBoolean(false)

    fun requestShutdown() {
        shutdownRequested.set(true)
        if (!processingActive.get()) {
            shutdownLatch.countDown()
        }
    }

    fun awaitShutdown() {
        shutdownLatch.await()
    }

    fun processFileManifest(manifestPath: String): List<UserFileRecord> {
        if (shutdownRequested.get()) return emptyList()
        processingActive.set(true)

        try {
            val manifest = File(manifestPath)
            if (!manifest.exists()) throw IllegalArgumentException("Manifest not found")

            val records = mutableListOf<UserFileRecord>()
            manifest.bufferedReader().useLines { lines ->
                lines.forEach { line ->
                    if (shutdownRequested.get()) return@forEach
                    val parts = line.split("|")
                    if (parts.size >= 3) {
                        val userId = parts[0].trim()
                        val fileName = parts[1].trim()
                        val action = parts[2].trim()
                        val userInfo = lookupUserPermissions(userId, fileName)
                        if (userInfo != null) {
                            records.add(UserFileRecord(userId, fileName, action, userInfo))
                        }
                    }
                }
            }
            return records
        } finally {
            processingActive.set(false)
            if (shutdownRequested.get()) {
                shutdownLatch.countDown()
            }
        }
    }

    private fun lookupUserPermissions(userId: String, resourceName: String): UserPermissionInfo? {
        val ctx = ldapPool.getContext()
        try {
            val controls = SearchControls().apply {
                searchScope = SearchControls.SUBTREE_SCOPE
                returningAttributes = arrayOf("cn", "mail", "memberOf", "filePermissions")
            }

            val sanitizedUserId = filterEncoder.encode(userId)
            val sanitizedResource = filterEncoder.encode(resourceName)
            val filter = buildPermissionFilter(sanitizedUserId, sanitizedResource)

            val results = ctx.search(baseDn, filter, controls)
            if (results.hasMore()) {
                val entry = results.next()
                val cn = entry.attributes.get("cn")?.get()?.toString() ?: ""
                val mail = entry.attributes.get("mail")?.get()?.toString() ?: ""
                val groups = entry.attributes.get("memberOf")?.let { attr ->
                    (0 until attr.size()).map { attr.get(it).toString() }
                } ?: emptyList()
                return UserPermissionInfo(cn, mail, groups)
            }
            return null
        } finally {
            ctx.close()
        }
    }

    private fun buildPermissionFilter(sanitizedUserId: String, sanitizedResource: String): String {
        // Build complex filter: user must match AND have resource access
        // Both parameters are already sanitized via filterEncoder
        return "(&(uid=$sanitizedUserId)(|(fileAccess=$sanitizedResource)(fileAccess=*)))"
    }
}

data class UserFileRecord(
    val userId: String,
    val fileName: String,
    val action: String,
    val permissions: UserPermissionInfo
)

data class UserPermissionInfo(
    val commonName: String,
    val email: String,
    val groups: List<String>
)

fun main() {
    val ldapUrl = System.getenv("LDAP_URL") ?: "ldap://localhost:389"
    val pool = LdapConnectionPool(ldapUrl)
    val encoder = Rfc2254FilterEncoder()
    val service = FileProcessingService(pool, encoder)

    Runtime.getRuntime().addShutdownHook(Thread {
        service.requestShutdown()
        service.awaitShutdown()
    })

    val manifestPath = System.getenv("MANIFEST_PATH") ?: "/data/manifest.txt"
    val results = service.processFileManifest(manifestPath)
    results.forEach { record ->
        println("Processed: ${record.userId} -> ${record.fileName} [${record.action}]")
    }
}
